NOTES_26=[
dict(n=1,title='课程出发点与分词',chapters='01、02',
core=[('模型、生成与训练','模型根据上下文给下一 token 分配概率。生成时再用某种规则选 token，并把结果接回上下文。训练则调整参数，让真实训练文本的概率更高。分词器决定模型处理哪些单位；它与预测这些单位的神经网络是两个组件。'),('效率的含义','同样预算下，减少显存搬运、避免训练无用数据、合理选择模型大小，都可能让最终模型更好。优化一个小模型上的热点，不能保证大模型也得到相同比例的收益。'),('BPE 的两个阶段','训练分词器时，从字节序列统计相邻对，反复合并常见对，得到词表与合并规则。编码新文本时使用已有规则；它不会为每个新句子重新训练。常见片段可成为一个 token，罕见片段退回更小单位。')],
oral=[(300,450,'课堂展开','小模型并不代表所有大模型行为。课堂用 Attention 与 MLP 所占计算比例随规模改变，说明局部优化的价值会随模型变化。这里只保留结论，不把当时示例数字作为通用比例。'),(4300,4550,'例子与代码讲解','课堂从未见过的词和 UNK 的问题转入字节级 BPE，随后逐步合并字节对。可逆性依赖完整的字节基础与正确的编码、解码实现，不能仅凭“用了 BPE”就保证无损。')],
qa='本次核对片段主要是讲者解释；未把课程介绍中的自问自答伪装成学生提问。',
demo='教学重建 D01：对短字符串逐步合并相邻字节对，比较训练前后的 token 数。看清“训练规则”和“使用规则”的区别。',
check='换成一个没见过的名字，分词器为什么仍可能表示它？',gap='板书和实际代码输出未逐帧核对；课堂历史与模型成本只保留为带年份背景。'),
dict(n=2,title='张量、精度与资源核算',chapters='00、03、04、09',
core=[('张量先看形状','把张量看作带形状、类型和设备的数字集合。矩阵乘法把输入维度变成输出维度；einsum 用轴名说明哪些轴相乘、哪些轴求和。形状相同不代表内存布局相同，reshape 与 transpose 也不总是复制数据。'),('精度有两个维度','指数范围决定能表示多大或多小的值，尾数精度决定相近数能分得多细。BF16 与 FP16 都占两个字节，但范围和精度分配不同。低精度还可能使用一组数共享缩放因子，不能把每个数孤立理解。'),('算得快还是搬得慢','FLOPs 数运算次数；FLOP/s 是速度。算术强度等于运算量除以内存搬运字节数。roofline 用带宽限制和计算峰值估计性能上界；真实程序还受调度、同步和布局影响。'),('训练显存','参数之外，还要保存梯度、优化器状态和反向传播所需激活。梯度累积把大 batch 分成小批次；重计算则减少保存的激活。二者主要解决内存问题，不承诺降低总计算量。')],
oral=[(930,1040,'问答','块缩放使低位宽数值共享一个缩放范围，但同一块内数值差异过大仍然困难。课堂也区分了低比特推理与训练，不能把推理量化经验直接当作训练配方。'),(1598,1665,'问答','把二维张量铺成一维时，轴顺序决定排列。einsum／rearrange 的写法需要显式表达这个顺序。'),(2112,2220,'计时演示解释','GPU 调用通常异步返回。只计 Python 调用返回时间可能漏掉实际计算；计时需要合适的同步、预热和重复。')],
qa='先让学习者解释“省一半字节”能改变什么，再区分显存容量、搬运量与数值误差。',
demo='教学重建 D04：比较一次大 batch 的平均梯度，与两个小批次累积后再更新的结果。官方代码中的 GPU 计时只解释方法，不给出本机未测量的吞吐量。',
check='把 batch 拆成两次，为什么不能在每个小批次后都更新参数，再称它与一次大 batch 完全等价？',gap='课堂跳过了部分训练循环；对应知识由讲稿与 A1 补足。FP4／FP8 硬件配方未作为通用建议。'),
dict(n=3,title='Transformer 结构与超参数',chapters='05、06、07',
core=[('注意力怎样取信息','Q 与 K 的匹配分数经缩放和 softmax 变成权重，再加权组合 V。因果遮罩禁止当前位置使用未来 token。多个头提供多组投影；它们不等于人工指定的语法专家。'),('残差与归一化','残差把输入直接加到变换结果，保留较直接的信息和梯度路径。pre-norm 把归一化放在子层之前。RMSNorm 不减均值，分母为 sqrt(mean(x²)+ε)，再乘可学习 gain；部分讲义公式漏了均值中的1/d，不能直接照抄。计算与搬运是否更省需看实际实现和任务。'),('位置、门控与稳定性','RoPE 对 Q、K 做随位置变化的旋转，使点积可反映相对位置。SwiGLU 用一条分支调制另一条分支。QK norm、z-loss 与 logit soft-capping 针对不同位置的数值失稳，不能互相当成同一个技巧。'),('超参数是取舍','深宽比、头维度、FFN 比例、词表和正则化会改变质量、成本与并行方式。论文里的常用比例是经验起点，不是数学必然。')],
oral=[(900,1080,'课堂展开','讲者用 RMSNorm 说明 FLOPs 少不等于运行快：少搬一次数据可能比少做一点算术更重要。'),(3408,3560,'问答与比较边界','讨论不同分词器的语言模型评价。per-token perplexity 受切分粒度影响；若比较原始字符串的概率，还要确保原始文本、规范化和计量单位一致。字幕中部分追问不清，未补造结论。'),(3866,4000,'问答','weight decay 除了传统的防过拟合作用，还会与学习率和优化动态相互影响。不能把预训练中所有正则化作用都解释成“数据太少”。')],
qa='不同 tokenizer 下的困惑度不可直接横比。换成按字节计的损失，也仍要控制原始文本和预处理。',
demo='教学重建 D02：计算一个很小的因果 Attention 表。改变未来位置的 V，检查早先位置的输出不变。图中的颜色和屏幕参数未作为已复现证据。',
check='为什么 Transformer 可以在训练时并行算多个位置，生成时却通常逐 token 前进？',gap='多模态词表及若干提问存在听不清片段；不据此给出某个现役模型的确切词表规格。'),
dict(n=4,title='Attention 替代路线与 MoE',chapters='07、08',
core=[('改变 Attention 的成本','滑动窗口只保留局部历史；稀疏注意力选择一部分位置；线性注意力重写计算并用紧凑状态汇总历史。这些方法对保留信息的方式不同，不能仅按复杂度排序优劣。'),('线性并不等于原算法','去掉或改写 softmax 后，某些乘法可先算 KᵀV，再与 Q 相乘。但一般不能随意交换原 softmax Attention 的计算顺序并声称完全等价。递推状态让推理成本减少，也引入信息压缩的限制。'),('MoE 在哪里稀疏','通常把一个 FFN 换成多个专家，由 router 为每个 token 选择少数专家。总参数决定存储等成本，激活参数更接近每 token 的计算规模。router、共享专家及加权方式仍需计算。'),('为什么负载均衡重要','路由过度集中会让部分专家忙、部分专家闲，也可能伤害训练。辅助损失、噪声和路由偏置是不同处理办法；稀疏选择、网络通信与容量限制一起决定实际收益。')],
oral=[(1200,1900,'课堂展开','线性、混合和稀疏方案都在解决长上下文问题，但压缩历史与保留原 token 的区别会影响任务。复杂度下降不是准确率保证。'),(2733,2845,'课堂讨论','MoE 普及受基础设施复杂、模型分布到多设备和训练不稳定等限制。课堂明确把更少 FLOPs 与更难用的系统放在一起讨论。'),(3600,4100,'推导与实验解释','top-k 路由的离散选择、专家负载和梯度目标需要一起看；去掉负载均衡损失的实验不能只看语言模型损失，还要看系统利用率。')],
qa='本讲部分问题由讲者提出，未一律标为学生问答。',demo='用四个 token、三个专家画出 top-1 路由表。比较全部 token 去同一专家和均匀分配时的等待；这是教学重建，不是课堂跑分。',
check='一个总参数更大的 MoE，为什么既可能省计算，又可能更难放进显存？',gap='索引器图、路由图与消融曲线未逐帧核对。现役模型案例保留为课程时点案例。'),
dict(n=5,title='GPU、TPU 与 FlashAttention 的硬件直觉',chapters='09、10、12',
core=[('处理器为何不同','CPU 强调较复杂控制与低延迟；GPU 用大量并行工作提升吞吐。GPU 的线程组成 warp 和 block，block 调度到 SM。寄存器、片上共享内存、缓存和 HBM 的速度与容量不同。'),('数据移动的代价','把 GPU 想成工厂时，HBM 像仓库，片上内存像工作台。反复把中间结果运回仓库会很贵。融合、分块和重计算都在改变搬运量，但实际容量、同步和依赖仍然存在。'),('分块与尾部浪费','tiling 让数据装入快内存后多次使用。块大小也影响可并行的块数；分不均时，最后一批工作可能只占用部分 SM，形成阶梯状性能。不是矩阵元素多一点就一定只慢一点。'),('FlashAttention','普通实现可能把很大的注意力中间矩阵写入 HBM。FlashAttention 分块，并用稳定的在线 softmax 合并统计量，计算精确 Attention 而不保存整个中间矩阵。反向可重新计算部分量。')],
oral=[(1650,2000,'图与例子解释','课堂把 roofline、内存距离和分支执行联系起来：分支两侧都存在工作时，同一 warp 不一定能真正并行执行两条路径。'),(2850,3150,'工厂类比与计算图','算子融合减少中间结果的反复读写；激活重计算增加一些算术，却可能降低内存需求。不要由此推断重计算在所有设备上都更快。'),(3900,4200,'曲线解释','矩阵尺寸与 tile、SM 数量不对齐，会出现性能跳变。重建只说明机制，不复制视频中的具体带宽数字。')],
qa='音频补核已补GPU图层次、Tensor Core、重复加载与预取问答；学生缺词不逐字恢复，见第十节。',demo='画一个 SM 数有限、任务块数不能整除的调度表。让学习者指出最后一轮空闲位置；FlashAttention 的在线归一化用 D03 的数值稳定思路连接。',
check='为什么“多做一点运算”有时能让模型更容易训练，甚至运行更快？',gap='TPU 结构图、低精度布局和 FlashAttention 图中数据流需要画面复核；未运行 GPU kernel。'),
dict(n=6,title='计时、融合与 Triton kernel',chapters='10、11、12',
core=[('先定位再优化','端到端计时告诉你总体速度，profiler 帮助定位耗时。预热排除部分初始化与编译开销；同步避免把 GPU 未完成的工作漏计。profiler 本身也有开销，不能把它的所有耗时都当作正常执行耗时。'),('一个 kernel 的骨架','确定程序负责的索引，生成地址，读入数据，执行运算，再写回。mask 处理超出有效长度的位置；stride 决定如何从逻辑索引走到内存地址。'),('高层代码与实际执行','Triton 代码描述分块计算，编译器生成更低层代码，并安排线程、寄存器等资源。Python 中出现一个 load，不代表 GPU 正在逐行调用 Python 库。'),('例子递进','GELU 适合看融合；softmax 包含按行归约与数值稳定；行求和引出分块；矩阵乘法进一步引出数据重用、共享内存和累加器。')],
oral=[(1244,1355,'问答','同一 SM 可以容纳什么工作受资源限制。尾部浪费不能简单靠把一个 block 任意拆给其他 SM 消除，改变 block 大小也会改变其他成本。'),(2874,3050,'问答','讲者解释 tl.load 与 HBM 地址、编译后执行之间的关系。把编程模型和硬件动作分开，是这段问答的重点。'),(3207,3385,'问答','同一段已编译代码可由多个线程运行，线程／块 ID 使其处理不同数据。一般不必手写 PTX；这不是禁止深入低层，而是说明通常的开发层次。'),(3892,4010,'问答','按列做 softmax 需要改变地址与 stride 的计算。能表达同一数学操作，不保证内存访问性能也相同。')],
qa='保留“代码写了什么”和“硬件怎样执行”两层回答；不要用 CPU 逐行解释代替 GPU 执行模型。',demo='重建 GELU 多算子与融合版的计算图，数中间张量读写。课堂 kernel 的屏幕输出只作定位，未在本机运行性能比较。',
check='改变 stride 后结果正确，是否说明访存效率也保持不变？',gap='视频标题含 XLA，但本次字幕未确认有独立 XLA 教学段；不据标题补造内容。已检查指定 profiler/PTX 帧及官方 trace；未覆盖所有界面切换与内核。'),
dict(n=7,title='通信原语与分布式训练代码',chapters='13、14',
core=[('rank 是谁','rank 通常标识参与通信的进程；课堂例子采用一进程一 GPU。不要推广成“rank 在任何系统中都等于 GPU”。通信操作还需要共同的进程组、形状与调用顺序。'),('三种基本结果','all-reduce 让每个参与者取得归约后的完整结果；reduce-scatter 让每个参与者只得一片归约结果；all-gather 再把这些片拼起来。操作组合可以等价，但具体通信算法和开销仍可不同。'),('网络与操作分开','RDMA 描述远程内存访问能力，NVLink、交换机、InfiniBand 等涉及实现与互连。节点内外带宽、延迟和拓扑可能不同；多一张跨节点卡不一定更划算。'),('训练怎样切','数据并行切 batch 并同步梯度；张量并行切层内矩阵；流水线并行切层并传递激活。前向通信往往还需要对应的反向通信，单靠普通 backward 不会自动创建分布式设计。')],
oral=[(267,335,'演示边界','讲者明确说明：逐行 trace 采用特殊单进程展示模式，真正多进程运行的标准输出另有入口。阅读动画不能误认为看到了实际并发调度。'),(1935,2010,'问答','区分 RDMA 的操作含义与网络硬件名称。'),(2084,2160,'问答','九张 GPU 是否合理取决于第九张卡位于哪里、怎样互连，不能只按卡数推算性能。'),(3652,3750,'问答','数据并行的 local batch 需要与 world size 协调；非整除情况还要处理样本权重与填充。'),(4088,4180,'问答','all-gather 的反向与 reduce-scatter 有联系，自动微分是否处理通信取决于所用分布式算子和封装。')],
qa='课堂有“平均参数”的口头表述；教学资料以官方训练代码为准，写成平均梯度，再由一致的优化器状态更新各副本。',demo='教学重建 D05：四个参与者输入 [0,1,2,3]+rank；all-reduce 得 [6,10,14,18]。再展示 reduce-scatter 加 all-gather 的同一结果。',
check='如果两个进程以不同顺序调用通信操作，为什么可能无法继续？',gap='没有实际启动多 GPU 进程，也没有把单进程教学 trace 当作通信性能证据。'),
dict(n=8,title='并行策略、分片与网络拓扑',chapters='13、14',
core=[('分片在分什么','DDP 复制训练状态；ZeRO 分阶段切优化器状态、梯度与参数。FSDP 通常需要在使用参数前收集参数片段，再在适当时机释放或重新分片。省显存不等于不付通信成本。'),('流水线的气泡','把层分给设备后，前后设备必须等待依赖。microbatch 让多个批次处在不同阶段，改善利用率，但还受激活内存、调度和批量限制。'),('组合并行','张量、流水线、数据、序列、上下文和专家并行各切不同轴。选择方式需同时看单卡内存、拓扑、通信量和训练 batch。')],
oral=[(1102,1205,'自动转写＋讲义对照','课堂在所用通信记账模型中比较 DDP 与 ZeRO-1：reduce-scatter 分发梯度，all-gather 收集更新参数，从而节省复制的优化器状态。近似相同的通信字节量不等于真实运行完全没有额外调度成本。'),(2600,2690,'自动转写＋讲义对照','课堂把张量并行与流水线并行的选择联系到互连拓扑。TPU mesh 与 GPU 节点内外带宽是该讲案例；不能将某代硬件的拓扑概括成所有后续设备。'),(3807,3890,'自动转写中的问答，概念经讲义核对','后段讨论 MoE 能否使用流水线、FSDP 等策略。资料只保留“可以组合，但专家并行有额外分组与通信约束”这一讲义支持的概念，不逐字恢复含糊的提问。')],qa='本地 base.en 自动转写有明显术语误识别。开头一次提问不清，未据此编写问句或答案。上述条目只保留可由讲义交叉确认的概念。',
demo='由官方 PDF 重建“谁保存参数、梯度、优化器状态”的分片表；通信量须声明按设备、按步骤还是全系统统计。',check='ZeRO-3 比复制所有参数更省显存，为什么可能需要额外 all-gather？',
gap='官方字幕仍返回请求封锁；已用原始英文音频本地转写 1,702 段作为低置信度导航。不是官方字幕，术语、公式和完整问答仍需听校；具体画面核对范围见演示帧清单。'),
dict(n=9,title='Scaling laws：规律、拟合与外推',chapters='16',
core=[('曲线描述什么','幂律形式可以用 L(x)=L∞+a·x^(−α) 表示。x 是数据、参数或计算等某个量，L∞ 是在该模型假设下的下限。双对数直线只在相应形式和区间内成立，不能从一小段拟合推出永远成立。'),('计算预算的取舍','更大的模型每个 token 更贵；更多数据需要更多训练步。固定预算下，要在模型规模与数据量之间分配。Chinchilla 的多种拟合方法依赖训练配方、学习率安排和计算记账方式。'),('三种方法','可以从多次训练的最优包络读预算表现；沿相同 FLOPs 扫模型大小；也可以联合拟合模型量和数据量。比较结论前，先检查每种实验是否得到足够训练、是否公平调参。'),('边界','重复数据、分布变化、选择质量和下游指标都会改变观察到的规律。训练损失最优，也未必是考虑服务成本后的最优部署选择。')],
oral=[(630,710,'问答','讲者明确把这些规律描述为经验拟合。理论能提供候选函数形式，却没有唯一的“黄金公式”。'),(900,1080,'例子','均值估计帮助理解误差随样本量下降的幂次。它解释一种简单来源，不等于证明语言模型的指数。'),(4050,4460,'方法比较','参数计数、嵌入参数、学习率 schedule 与拟合误差可能改变论文之间的结论；不能把某个固定 token／参数比当作永恒常数。')],qa='区分“用理论理解某种趋势”和“该理论已推导出现有大模型的精确曲线”。',demo='画同一计算预算下三种模型／数据组合。先问哪些变量必须固定，再讨论如何寻找最低验证损失。',check='只知道训练 loss 随算力下降，为什么仍不能直接知道聊天回答会提高多少？',gap='原图拟合点、置信区间和所有图中读数未逐帧核对；不输出未经复核的精确缩放指数。'),
dict(n=10,title='推理：从 KV cache 到动态服务',chapters='07、15',
core=[('prefill 与 decode','prefill 处理已有上下文，许多位置可并行；decode 反复生成新 token。KV cache 保存过去位置的 K、V，减少重复计算，但缓存随请求和上下文增长。模型权重可在 batch 内共享读取，缓存通常随请求分别保存。'),('吞吐与延迟','大 batch 可能摊薄权重读取，提高总体吞吐，却也可能让单个请求等待更久。必须说明测量的是首 token 延迟、输出 token 间隔，还是整段完成时间。'),('有损与无损捷径','量化、剪枝或结构改动可能影响输出质量。推测采样先用便宜模型拟候选，再由目标模型按正确规则接受或拒绝；保持目标分布需要完整接受与残差采样规则，不是只检查“看上去合理”。'),('请求是动态的','请求起止时间和输出长度不同。连续批处理及时补入新请求；分页式 KV 管理减少连续预留带来的空间浪费。它们改善调度和存储，不会让逻辑上下文无限长。')],
oral=[(3560,3690,'问答','线性状态、滑动窗口和全注意力保留历史信息的方式不同，可以混合使用；不能只比较缓存大小。'),(4240,4330,'问答','激活很大不自动代表不可删除的语义特征，还可看方差和其他统计；但也不能随手删掉恒定大值。'),(4789,4935,'问答与类比','课堂用旧式磁盘碎片解释 KV cache 的内部和外部碎片，再引入分页。类比只说明空间管理，不表示 GPU 缓存与磁盘完全相同。')],qa='把固定模型的调度优化与换模型结构分开比较，避免把质量变化隐藏在速度改进里。',demo='用三个不同长度请求画固定批处理与连续批处理时间表，分别观察空闲位置与等待时间；不提供未实测的加速倍数。',check='批量变大后吞吐变高，为什么用户仍可能觉得变慢？',gap='缓存图、性能主图及关键帧已查看；未全帧审片，带硬件型号的延迟数字是原课/论文配置，不作为本机实测。'),
dict(n=11,title='Scaling 的实践、μP 与优化器',chapters='04、17',
core=[('超参数需要迁移','扩大宽度会改变激活和更新的尺度。μP 通过初始化和分层学习率等规则，力求让合适的设置跨宽度更稳定；它不是只换一个全局学习率，也不保证跨深度、任务和所有结构都成立。'),('实验复用','WSD 把 warmup、稳定阶段和 decay 分开，让不同预算的实验有机会共用前面的训练。复用时仍需比较 schedule 的公平性，不能把中途 loss 当最终同等质量。'),('优化器是算法加实现','Muon 利用矩阵结构和近似正交化更新。课堂讨论用 Newton–Schulz 的矩阵乘迭代，而不是每次做昂贵的完整 SVD。是否更好需在多个计算规模和合理调参后比较。')],
oral=[(1771,1855,'问答','把预训练与后训练联合考虑的 scaling，在本讲时点仍没有统一成熟答案；资料保留这个开放边界。'),(2400,2750,'比较方法','新优化器在小模型上的领先可能在更大预算消失。要检查横轴定义、调参投入和规模依赖，不只看单点成绩。'),(3303,3415,'问答','SVD 的成本问题不等于 Muon 实现成本；讲者强调近似正交化算法和系统实现也是方法的一部分。')],qa='不要把经验有效的参数迁移规律讲成对所有网络的数学保证。',demo='比较两个宽度下未控制的激活尺度，再说明为什么需控制初始化和更新；公式推导按需要拆开，避免一次引入全部 μP 条件。',check='比较 AdamW 和 Muon 时，为什么应分别调学习率，而不是强制共用一个数？',gap='优化器图表、具体参数配方和全部 μP 推导细节仍以官方讲义为深读来源；未复现大型训练。'),
dict(n=12,title='评估：分数怎样产生，又怎样失真',chapters='18',
core=[('困惑度','平均负对数似然衡量模型给真实文本的概率，perplexity 是它的指数。切分粒度、文本预处理和评估数据都影响结果；跨 tokenizer 直接比较 per-token 数字可能没有意义。'),('基准测的是系统','选择题的提示、答案提取和是否生成推理会改变分数。聊天偏好还混合正确性、风格与用户群体。智能体评估同时包含模型、工具、上下文组织和执行环境。'),('污染与效度','不直接训练测试题，也可能见过题目来源或同源材料。能通过单元测试不保证满足用户目标；安全评价也必须先定义风险、使用场景和测试边界。')],
oral=[(1604,1680,'问答','测试污染可能来自题目的原始来源，不能只查完全相同的测试文本。'),(1879,1955,'问答','生成字母、生成解释后提取答案等流程会改变评价；所谓同一模型得分需要说明评测协议。'),(2161,2290,'课堂讨论','Arena 类投票来自特定用户分布；胜出可能受风格影响。类似 Elo 的显示方式并不把“哪个回答更好”变成像棋局胜负一样清晰。'),(3576,3650,'问答','图形推理任务可用图像或文本／ASCII 表示输入，表示选择本身会改变任务。')],qa='先定义你要测的能力和使用场景，再选择评测方式。',demo='把同一回答分别按事实正确、格式符合和语气偏好打分，展示一个总分会怎样隐藏差异。此为教学设计，不是重新跑课程榜单。',check='一个智能体补丁通过全部现有测试，为什么仍可能没有真正修复问题？',gap='排行榜与新基准的当前分数未更新；图形题和安全演示画面未逐帧复核。'),
dict(n=13,title='数据来源、抓取与使用边界',chapters='19',
core=[('来源决定可学到什么','网页、书籍、代码、百科和论文有不同风格、覆盖与噪声。把多个数据集名字背下来不如理解它们如何收集、清洗、许可和采样。相同 token 数不意味着相同有效信息。'),('抓到不等于可直接训练','抓取结果可能包含导航、重复、敏感信息、恶意内容和不适合目标任务的文本。Common Crawl 提供抓取材料，开发者仍需自己的转换、过滤、去重和来源记录。'),('许可与版权讨论如何保留','公开可访问、robots 规则、网站条款、版权许可和可用来训练是不同问题。本资料只解释课程讨论的区别，不把课堂对诉讼、fair use 或许可变更的推测升级成当下法律结论。')],
oral=[(1893,1985,'问答','有人问许可随时间变更。课堂回答带有明确的不确定性；学习资料保留问题，并要求实际使用时核对具体版本、内容、条款与适用法律，不能抽成通用授权规则。'),(2619,2730,'问答','网络抓取可能碰到不应使用的来源，规模化并不自动解决来源合法性。合成数据也不能仅凭“模型生成”跳过来源和使用条件检查。'),(4200,4380,'数据例子','代码数据不只有文件内容，还涉及仓库、提交和去重单位。编译或运行验证是特定数据处理手段，不等于所有代码文本都已被验证。')],qa='把“来源是什么”和“课程如何使用它”分开，不暗示学习资料附带这些数据的使用许可。',demo='用一个虚构网页展示原始 HTML、正文、链接和来源记录四层；不抓取私人网站，也不复制课程数据集。',check='为什么一个完全公开的网页也需要记录来源和使用条件？',gap='课堂涉及的法律和诉讼背景未做当前法律核查；不作为法律建议或可训练数据清单。'),
dict(n=14,title='过滤、去重、混合与合成数据',chapters='20、21、22',
core=[('转换与过滤','HTML／PDF 转文本要尽量保留有用结构。规则、语言识别、模型评分各有偏差；过滤标签的含义应与训练目标一致。最终需要通过训练实验验证，而不只是看被保留文本是否“漂亮”。'),('近似去重','把文档表示为 n-gram 集合，Jaccard 是交集大小除以并集大小。理想 MinHash 的碰撞概率等于相似度 s。LSH 用 b 个 band、每 band r 个哈希，候选碰撞概率为 1−(1−s^r)^b；它是概率筛选，不是确定阈值判定。'),('混合不只是百分比','若总训练 token 数为 T，来源 i 的采样权重为 w_i，来源可用 token 数为 D_i，预期经过该来源的轮数约为 T·w_i/D_i。高权重的小来源可能被无意重复很多次。'),('合成数据的验证','合成任务、答案和智能体轨迹需要检验目标、难度、正确性、泄漏和多样性。自动生成环境不等于奖励没有漏洞。')],
oral=[(1234,1345,'问答','重复训练以估计置信区间更理想，但成本会限制实验次数；即使结果看似稳定，也不应伪造统计置信度。'),(2280,2490,'算法演示','课堂用 12 个哈希分成 3 个 band、每 band 4 个解释如何把相似度转成更陡的候选概率。'),(3397,3505,'问答','出现几十个 epoch 不表示需要训练那么多次，可能只是混合配方造成的隐性重复。课堂建议检查每个来源的实际轮数。'),(4252,4345,'问答','极小来源在下采样后可能因取整丢失，混合算法仍要考虑有限样本。')],qa='MinHash 估相似性，LSH 找候选；不要把两者合并成“精确删除所有近重复”。',demo='教学重建 D06：计算不同 Jaccard 相似度下 3×4 LSH 的候选概率；再用来源轮数公式检查一个小数据源的重复。',check='把高质量来源权重调高，为什么既可能改善模型，也可能造成重复过多？',gap='PDF转换、混合图和合成轨迹的讲义主图与关键帧已核对；未逐帧运行现场流程。概率推导声明理想哈希假设。'),
dict(n=15,title='SFT、偏好数据与 RLHF',chapters='22、23、24',
core=[('SFT 的目标','用输入和目标回答训练条件概率，常见对话训练只在 assistant 回答上计损失。它与预训练共享预测机制，但数据、格式、目标分布和训练阶段不同。具体 loss mask 以实际配方为准。'),('风格不等于事实','少量示范可能很快改变回答格式和语气，却未必让模型可靠掌握新知识。缺乏知识时强制模仿详细回答，可能增加编造。安全微调也需同时看误拒绝与漏拒绝。'),('从模仿到偏好优化','人可能擅长比较两份答案，却写不出最好答案。RLHF 使用偏好、奖励与策略更新改善输出，同时常用 KL 等约束避免过度偏离。DPO 直接使用偏好对与参考策略的相对概率构造目标，不需显式在线 PPO 循环。'),('奖励与事实之间','标注者可能有共同偏见，模型评审也可能偏好长度和风格。奖励过优化和模式收缩说明“更高奖励”不能单独证明更好、更真实或更校准。')],
oral=[(2333,2470,'问答','课堂讨论 decay 阶段的数据质量与中后训练混合。接近最终模型、学习率较低的阶段常被用于更精选数据，但这是经验配方，不是无条件规律。'),(3408,3525,'问答','标注者之间一致性衡量分歧，不能证明没有共同偏差。大家都依赖同一个模型时，一致也可能只是复制同一偏差。'),(3560,3675,'问答','模型辅助标注有价值，但领域专用模型是否更好要看能力和验证，不能从“专用”二字直接判断。')],qa='SFT、RLHF 与 DPO 是训练方法，不是事实核验器。',demo='给两份答案分别标注事实、风格和长度偏好，构造一对偏好数据，再指出奖励可能学到的捷径。',check='所有标注者都选同一个答案，为什么仍不能保证答案正确？',gap='众包薪酬、平台与人口分布等时点数字未更新；不纳入长期知识结论。'),
dict(n=16,title='RLVR、GRPO 与推理模型',chapters='24、25',
core=[('把生成视为策略','问题是输入，生成过程是轨迹，评分器给回报。策略梯度增加高于基准的轨迹概率、降低低于基准的轨迹概率。基准旨在减少估计噪声，其设计与采样方式关系很大。'),('PPO 与 GRPO','PPO 常使用 value 模型估计 advantage，并限制新旧策略概率比的更新。GRPO 用同一问题的多个回答形成比较组，可省去独立 value 网络；组内均值、标准差和长度归一化会改变不同样本的权重。'),('为什么长推理要小心','输出变长可能有帮助，也可能来自归一化偏差，尤其应分开看正确和错误回答的长度。奖励可验证不等于训练信号完美，评分器、格式和环境都可能被利用。'),('训练阶段的配合','长 CoT SFT、RLVR、通用偏好优化、蒸馏和智能体训练可按不同配方组合。学习资料保留这些组合的目的和取舍，不给所有模型套同一流水线。')],
oral=[(2321,2415,'问答与曲线解释','课堂把正确与错误回答的长度拆开，说明总体 CoT 增长不能单独证明推理更好。'),(4239,4350,'问答','本讲所举 thinking／non-thinking 案例通过同一模型的提示标记控制，不应推断所有 API 的模式切换都采用同一种内部机制。'),(4432,4525,'问答与明确缺讲','讲者表示没有充分展开长上下文扩展，并解释它常是另一个阶段。资料明确保留这项深度缺口，不把提到过当作已完整教授。')],qa='把“最终答案可判对错”与“思维链每一步都正确、忠实”分开。',demo='教学重建 D07：同一问题生成四个有不同回报的回答，计算组均值和中心化回报。再检查奖励全相等时的更新信息。',check='四个回答都答错且奖励相同，组内比较还能告诉模型哪个更好吗？',gap='完整长上下文扩展配方课程未展开；具体 GRPO 变体的实现细节由当前 A5 补充，未复现大模型 RL。'),
dict(n=17,title='多模态：视觉表示接到语言模型',chapters='27',
core=[('图像怎样进入模型','视觉编码器把图像变成向量序列，连接器把它映射到语言模型能使用的表示空间。视觉 token 不一定来自文字分词器的离散词表。分辨率、裁剪与帧数影响序列长度和成本。'),('CLIP 与 SigLIP','对比学习让匹配图文表示接近、不匹配表示可区分。CLIP 的 batch 内对比与 SigLIP 的成对 sigmoid 目标不同；图文匹配能力不等同于会进行多轮视觉对话。'),('对齐与指令训练','某些 LLaVA 阶段冻结视觉编码器和语言模型，只训练连接器；后续阶段可能解冻更多参数。先有较好的语言与视觉表示，连接器才有可对齐的内容。'),('输入多模态与输出多模态','能读图并输出文字，不等于能生成图像或视频。原生多模态生成还涉及视觉离散编码、目标和稳定性；不能把所有模型都按“图像前加一个 adapter”概括。')],
oral=[(2636,2740,'例子','课堂用表格、图表和多图推理说明不同训练技能可能组合迁移到新情境；这不是对任意组合都成功的保证。'),(3594,3700,'问答','讲者明确当前讨论的一组模型在输出端只生成文字，图片和视频主要在输入端。随后另讲可生成视觉内容的路线。'),(3803,3890,'问答','连接器对齐阶段所用语言模型已预训练；不把冻结策略推广到所有阶段。')],qa='先问“这个模型的输入和输出分别是什么模态”，再解释结构。',demo='画出图片 → patch 向量 → 连接器 → 与文字合并 → 语言模型 → 文字回答。用同一图说明高分辨率为什么增加成本。',check='一个模型会描述视频，为什么不能据此推断它会生成视频？',gap='图片裁剪、M-RoPE与视频位置讲义主图已核对；未完整逐帧验证原示例视频。视觉生成与diffusion仍为课程概览深度。'),
dict(n=18,title='Dan Fu：推理系统、Megakernel 与循环模型',chapters='11、15、17、28',
core=[('从请求生命周期看系统','请求进入调度、prefill、decode、缓存和工具调用等环节。长代码输入、长推理输出与短聊天的负载形状不同；一种优化不必然适合所有负载。'),('缓存像需要管理的内存','多轮和工具调用产生可复用前缀与不同等待时间。把缓存放在 GPU、CPU 或更慢存储之间调度，需要考虑容量、传输、复用概率和尾延迟。操作系统类比帮助理解，但不提供最优策略保证。'),('Megakernel 的目的','多个单独高效 kernel 之间仍有启动间隙、尾效应和依赖等待。更大范围融合与细粒度调度可提前加载后续所需数据，但设计复杂、硬件与模型适配成本高。'),('循环模型的取舍','重复使用一组 block，让参数量与计算量更独立地变化；循环还可能放大状态和训练失稳。少参数可改变显存、缓存容量和跨卡通信需求，但是否改善质量和速度仍需实验。')],
oral=[(444,530,'明确的图示边界','讲者说明部分概览图由生成式工具制作，细小文字可能错误。资料只保留口述确认的高层流程，不抄图上的数字和标签。'),(1671,1790,'问答','缓存卸载与经典内存调度相似；LRU 是启发式，不是知道未来。未重复未经验证的最优性倍数说法。'),(2252,2445,'演示解释','讲者用 GPU 时间条说明更大范围融合，并解释可在 QKV／RoPE 尚未完成时准备某些后续数据。这里记录调度意图，不声称已核验原图各色条和跑分。'),(3000,3100,'数学边界','口述把谱半径近似说成 norm。教学资料使用准确区分：谱半径是特征值绝对值的最大值，一般不等于矩阵范数；负对角本身也不足以推出离散迭代收敛。具体稳定性需结合实际递推公式。'),(3817,3920,'问答','手写 Megakernel 的适配和维护成本很高。资料保留这个工程取舍，不把课堂的人年估计当作普遍成本标准。')],
qa='关于直接循环预训练模型是否普遍有效，讲者仍表示研究中。资料保留为开放问题。',demo='画出算子依次启动与可重叠调度的时间条；再用标量迭代 x←a·x 展示 |a| 小于、等于或大于 1 的区别。',check='减少参数但增加循环次数，为什么可能减少显存，却仍增加计算和延迟？',gap='独立本课讲义未取得；已用完整字幕、指定视频帧、作者论文和代码补充。性能图及其他画面没有全面逐帧核验，未核实的精确数值不纳入结论。')
]

# Earlier-year material is retained as an addition to, not a replacement for, 2026.
NOTES_25=[
(1,'课程与分词',1181,1255,'课程完成后的能力边界','问答明确表示这门课是理解和构建模型的第一步，不是从课程毕业即可掌握前沿模型团队的所有能力。分词与预算意识仍可沿用。','课堂分词编码示例；与 2026 L01 合并，不重复要求做 A1。'),
(2,'张量与资源核算',822,895,'混合精度中的持久状态','课堂用 FP32 的长期累积状态与低精度的暂态计算区分混合精度。它是当年示意配方；现在有不同训练方式，不能教成所有参数永远必须以 FP32 存储。','保留 storage、stride、view、contiguous、数据加载、随机种子和 checkpoint 代码例子。'),
(3,'结构与超参数',1102,1180,'比具体模型配方更可迁移的原则','课堂强调直接残差路径、控制激活尺度，以及结构对系统的影响。这比背某个激活函数名更适合初学者建立判断。','串行与并行 block 的比较、RoPE 的旋转解释，与新版对应章节合并。'),
(4,'MoE',382,490,'激活参数不是全部成本','问答指出，图上只画激活参数可能使比较显得更有利。需同时检查总参数、显存、设备间路由和真实 wall-clock。','用 top-k 加权和专家负载图解释稀疏计算；保留路由前后 softmax 的不同设计。'),
(5,'GPU',611,725,'物理距离与内存层级','课堂把 GPU 示意图对应到实际 SM 与内存，强调“会计算”只解释性能的一部分。临近处理单元的内存通常更快、更小，组织计算时需考虑位置。','保留工厂、sin²+cos² 融合、sigmoid 重计算、tile 与在线 softmax 例子。'),
(6,'Kernel 与 Triton',3557,3670,'连续内存与转置视图','课堂简单 kernel 假定连续布局；transpose／view 可能改变 stride。可以在外层整理布局或实现通用寻址，但这两条路有不同成本，不应把连续性断言当数学要求。','保留 CUDA 手写 GELU、torch.compile、profiler 与 Triton softmax 的比较；未运行 GPU 性能测量。'),
(7,'并行一',1403,1520,'通信量的统计口径','课堂追问通信量是每设备还是全系统。这段回答与后文不同公式存在口径混淆风险，教学资料不直接搬一个倍数。每次都说明发送／接收、单卡／总和、轮次与算法。','保留 ZeRO 分阶段示意、激活内存与 sequence parallel 的解释，补充缺字幕的 2026 L08。'),
(8,'并行二',730,795,'代码、拓扑与运行输出','课堂从设备连接转入 collective 代码，再到数据、张量、流水线并行。逻辑上等价的切分，仍会受实际拓扑和异步调度影响。','保留 reduce-scatter 后 all-gather 的数值输出、microbatch 和显式 send／recv 代码。不是 2026 L08 的替代字幕。'),
(9,'Scaling 一',645,735,'变大也可能有反例','课堂讨论逆 scaling 和分布外行为。预训练 loss 下降并不保证每个任务、每种提示下都单调改善；必须区分平均指标与具体行为。','保留均值估计、临界 batch 和 Chinchilla 方法比较。'),
(10,'推理',2217,2295,'请求到达与完成时间不同','问答把不同用户和不同输出长度引入批处理问题。缓存、调度与模型数学成本必须一起看，静态 batch 估算不是完整线上服务模型。','保留状态空间与 diffusion 的路线讨论，但不把课堂概览包装成已完整教授这些架构。'),
(11,'Scaling 二',1760,1855,'μP 不只改变初始化','课堂明确 μP 同时涉及初始化和分层学习率规则；在某些已有初始化下，学习率差异更显著。要把实现规则和理论条件对应。','保留线性网络的尺度推导及非线性、batch、初始化和正则化的消融边界。'),
(12,'评估',812,900,'自适应测试与可比性的矛盾','多轮对话和红队测试需要对模型回应作出反应；固定脚本未必真实。但不同模型面对不同测试，又使横向比较更难。测试设计需说明目标和控制条件。','保留静态／交互式评价、语料似然、智能体和安全评价的区别。'),
(13,'数据一',1096,1200,'数据供应方不替代自己的过滤','课堂认为 Common Crawl 包含敏感或有害材料，同时明确不确定其所有过滤细节。学习资料保留这种不确定性，不把猜测当供应方保证。','保留长上下文数据、指令任务和来源介绍。版权讨论只作当年背景，不写成当下许可结论。'),
(14,'数据二',652,735,'特征哈希与近似的代价','fastText 的 n-gram 特征空间很大，可用固定数量的桶哈希存储，接受一定碰撞。这与近重复检索中的 MinHash／LSH 不是同一种目的，不能混叫“哈希去重”。','保留 KenLM、Kneser–Ney、fastText、DSIR、重要性采样和 Bloom filter；这些旧版细节不被新版压缩讲次抹去。'),
(15,'SFT／RLHF',2374,2470,'表面格式与复杂条件关系','课堂用输出 emoji 的假想问题说明：SFT 可能学会输出风格，却没学会根据输入选择正确内容。能模仿样式不等于掌握目标能力。','保留事实引用、安全示范和偏好数据例子；不把“少量 SFT 只能学风格”教成普遍定律。'),
(16,'RL 一',1800,2450,'归一化改变训练权重','课堂对 GRPO 的组内中心化、标准差和序列长度展开推导。不同归一化不只是数值写法不同，可能改变问题难度和长短回答的权重。','已在音频补核补入GRPO分组、GRPO/PRM区别、CoT可读性与权重同步问答；不能恢复的学生原句仍保留缺口。'),
(17,'RL 二：完整小模型链路',1950,2160,'排序任务为何适合讲策略梯度','同一 prompt 可生成一组响应，组内平均奖励自然成为比较基准。模型参数更新后，后续响应分布也变化，所以 RL 的训练样本不是固定数据集。','官方示例模型按位置独立输出，并非自回归 Transformer。两种排序奖励、中心化、归一化、冻结旧策略、重要性比、clipping 和 KL 是独立可解释步骤。')
]
